CREATE TABLE public.entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name_ar text NOT NULL, name_en text NOT NULL UNIQUE, category text NOT NULL, official_domains text[] NOT NULL DEFAULT '{}', official_phones text[] NOT NULL DEFAULT '{}', brand_keywords text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.entities TO authenticated; GRANT ALL ON public.entities TO service_role;
ALTER TABLE public.entities ENABLE ROW LEVEL SECURITY;
CREATE POLICY authenticated_access ON public.entities FOR ALL TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);
CREATE TABLE public.search_phrases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phrase text NOT NULL UNIQUE, entity_id uuid REFERENCES public.entities(id), active boolean NOT NULL DEFAULT true);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.search_phrases TO authenticated; GRANT ALL ON public.search_phrases TO service_role;
ALTER TABLE public.search_phrases ENABLE ROW LEVEL SECURITY;
CREATE POLICY authenticated_access ON public.search_phrases FOR ALL TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);
CREATE TABLE public.hunts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phrase text NOT NULL, source text NOT NULL CHECK(source IN ('google','maps','manual')), results_count integer NOT NULL DEFAULT 0, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.hunts TO authenticated; GRANT ALL ON public.hunts TO service_role;
ALTER TABLE public.hunts ENABLE ROW LEVEL SECURITY;
CREATE POLICY authenticated_read ON public.hunts FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
CREATE POLICY authenticated_insert ON public.hunts FOR INSERT TO authenticated WITH CHECK (created_by = auth.uid());
CREATE POLICY authenticated_update ON public.hunts FOR UPDATE TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY authenticated_delete ON public.hunts FOR DELETE TO authenticated USING (auth.uid() IS NOT NULL);
CREATE TABLE public.links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hunt_id uuid REFERENCES public.hunts(id), url text NOT NULL UNIQUE, final_url text, domain text NOT NULL, platform text NOT NULL DEFAULT 'other', rank integer, title text NOT NULL DEFAULT '', snippet text NOT NULL DEFAULT '', maps_phone text, is_ad boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('official','pending','scanning','done','unscannable','error')), first_seen_at timestamptz NOT NULL DEFAULT now(), parent_link_id uuid REFERENCES public.links(id), depth integer NOT NULL DEFAULT 0 CHECK(depth BETWEEN 0 AND 2), scan_uuid text, scan_started_at timestamptz, scan_error text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.links TO authenticated; GRANT ALL ON public.links TO service_role;
ALTER TABLE public.links ENABLE ROW LEVEL SECURITY;
CREATE POLICY authenticated_access ON public.links FOR ALL TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);
CREATE TABLE public.analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), link_id uuid NOT NULL UNIQUE REFERENCES public.links(id), cf_scan_uuid text, impersonated_entity_id uuid REFERENCES public.entities(id), domain_age_days integer, age_source text NOT NULL DEFAULT 'unavailable' CHECK(age_source IN ('rdap','crtsh','unavailable')), page_title text NOT NULL DEFAULT '', outgoing_domains text[] NOT NULL DEFAULT '{}', phones_found text[] NOT NULL DEFAULT '{}', signals jsonb NOT NULL DEFAULT '{}', score integer NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100), level text NOT NULL DEFAULT 'green' CHECK(level IN ('green','yellow','red')), reasons_ar text[] NOT NULL DEFAULT '{}', ai_summary_ar text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.analyses TO authenticated; GRANT ALL ON public.analyses TO service_role;
ALTER TABLE public.analyses ENABLE ROW LEVEL SECURITY;
CREATE POLICY authenticated_access ON public.analyses FOR ALL TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);
CREATE TABLE public.engine_cache (key text PRIMARY KEY, value jsonb NOT NULL, expires_at timestamptz NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.engine_cache TO authenticated; GRANT ALL ON public.engine_cache TO service_role;
ALTER TABLE public.engine_cache ENABLE ROW LEVEL SECURITY;
CREATE POLICY authenticated_access ON public.engine_cache FOR ALL TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);
CREATE TABLE public.scan_gate (id boolean PRIMARY KEY DEFAULT true CHECK(id), last_started_at timestamptz);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.scan_gate TO authenticated; GRANT ALL ON public.scan_gate TO service_role;
ALTER TABLE public.scan_gate ENABLE ROW LEVEL SECURITY;
CREATE POLICY authenticated_access ON public.scan_gate FOR ALL TO authenticated USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);
CREATE FUNCTION public.claim_scan(_link_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RETURN false; END IF; INSERT INTO public.scan_gate(id) VALUES(true) ON CONFLICT DO NOTHING; PERFORM 1 FROM public.scan_gate WHERE id=true FOR UPDATE; IF EXISTS(SELECT 1 FROM public.scan_gate WHERE last_started_at > now()-interval '10 seconds') THEN RETURN false; END IF; IF EXISTS(SELECT 1 FROM public.links WHERE status='scanning' AND scan_started_at > now()-interval '120 seconds') THEN RETURN false; END IF; UPDATE public.links SET status='scanning', scan_started_at=now(), scan_error=NULL WHERE id=_link_id AND status='pending' AND NOT EXISTS(SELECT 1 FROM public.analyses WHERE link_id=_link_id); IF NOT FOUND THEN RETURN false; END IF; UPDATE public.scan_gate SET last_started_at=now() WHERE id=true; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.claim_scan(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_scan(uuid) TO authenticated;
CREATE INDEX links_status_idx ON public.links(status); CREATE INDEX analyses_level_idx ON public.analyses(level);
COMMENT ON TABLE public.engine_cache IS 'Public registry bootstrap cache only; never raw suspicious-page DOM or personal information';